// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    // fuzzed params: amount to deposit and a boolean that controls whether the attacker will re-enter
    function testFuzz_property(uint96 amount, bool attackerReenters) public {
        // keep amount reasonable and > 0 for meaningful deposits
        vm.assume(amount > 0);
        uint256 amt = uint256(amount);

        // deploy attacker helper that can re-enter exactly once
        Attacker attacker = new Attacker(c);

        // fund attacker so it can receive/forward ETH and also be msg.sender for deposit
        vm.deal(address(attacker), amt);

        // attacker deposits into c under its own address
        attacker.deposit{value: amt}();

        // prepare attacker behavior: allow it to reenter or not
        attacker.setShouldReenter(attackerReenters);

        // now call withdrawAll from attacker's address (the attacker contract will be the msg.sender)
        attacker.triggerWithdrawAll();

        // After withdrawAll completes on the reference contract, the attacker's recorded credit must be zero.
        // We observe credit by calling withdrawAll again and seeing if it tries to send any value (i.e., whether it's nonzero).
        // Strategy: call withdrawAll a second time and catch whether it sends ETH (success) or short-circuits due to zero credit.
        // To avoid consuming funds, we call via a recorder that captures calls from C. We'll use a helper "Recorder" that
        // provides a payable fallback and increments a counter when it receives ETH. But we cannot change c to send to Recorder;
        // instead, we infer credit by trying to withdraw again from the attacker address and observing whether C attempts to send value.

        // Make a fresh observer that will attempt to call withdrawAll as the attacker; if credit is zero, withdrawAll will do nothing.
        // We'll execute withdrawAll via try/catch and detect whether it attempted to send value by letting the caller accept ETH.

        // create a helper that will call c.withdrawAll as a proxy and record whether it received ETH during that call
        ProxyReceiver proxy = new ProxyReceiver(c);
        // fund proxy so it can be msg.sender if needed (not necessary but harmless)
        vm.deal(address(proxy), 1 ether);

        // Ask the proxy to call withdrawAll on behalf of the attacker address by having the proxy call withdrawAll() itself 
        // as msg.sender; but we need the call to be from the same address that had the credit: attacker. So have the attacker
        // perform the second withdraw through its own logic and record whether it receives ETH. Attacker exposes a view of whether
        // it received any ETH during the second withdraw attempt.

        // Reset attacker's internal receive counter before second attempt
        attacker.resetReceiveCount();
        // perform second withdrawal attempt from attacker (this will receive value only if credit was non-zero)
        attacker.triggerWithdrawAll();

        // Now assert: for the correct contract, after the first withdrawAll completes, the attacker's credit must be zero ->
        // second withdrawAll should not send any ETH, so attacker's receiveCount should still be 0.
        // The mutant (which clears credit after the external call) can leave credit non-zero after reentry and thus the second
        // withdraw may send ETH (receiveCount > 0) for some inputs; hence our assertion must be true for the reference and false
        // for the mutant on some inputs.

        // Read the recorded count from attacker (this is allowed: helper's public getter)
        uint256 recvd = attacker.receiveCount();

        assertTrue(recvd == 0);
    }
}

// Adversarial counterparty that can re-enter C once during receive()
contract Attacker {
    ReentrancyDAO public c;
    bool private __entered;
    bool public shouldReenter;
    uint256 public recvCount;

    constructor(ReentrancyDAO _c) payable {
        c = _c;
    }

    receive() external payable {
        recvCount += msg.value > 0 ? 1 : 0;
        if (shouldReenter && !__entered) {
            __entered = true;
            // re-enter withdrawAll while original withdrawAll in C is still in progress for the msg.sender
            // This triggers the reentrancy difference between reference and mutant
            c.withdrawAll();
        }
    }

    function setShouldReenter(bool v) external {
        shouldReenter = v;
    }

    function deposit() external payable {
        // forward deposit to c from this contract's address
        c.deposit{value: msg.value}();
    }

    function triggerWithdrawAll() external {
        // call withdrawAll from this contract
        c.withdrawAll();
    }

    function receiveCount() external view returns (uint256) {
        return recvCount;
    }

    function resetReceiveCount() external {
        recvCount = 0;
        __entered = false;
    }
}

// Minimal proxy receiver not used for core assertion but retained to respect allowed helpers (kept tiny)
contract ProxyReceiver {
    ReentrancyDAO public c;
    constructor(ReentrancyDAO _c) payable { c = _c; }
    receive() external payable {}
}
